QS=[
Q('מהו המקור לסמכות בג"ץ לדון בעתירות נגד רשויות?','ס׳ 15 לחוק יסוד: השפיטה (למען הצדק)',['חוק העונשין','הסכמה בין הצדדים','תקנות הכנסת'],'בג"ץ שואב סמכות מחוק יסוד: השפיטה. הסכמה בין הצדדים אינה נדרשת בעתירה כנגד רשות, וחוק העונשין ותקנות הכנסת אינם מעניקים סמכות כזו.'),
Q('מהו "עותר ציבורי"?','עותר בעניין בעל חשיבות ציבורית כללית ללא אינטרס אישי ישיר',['עותר שהוא נפגע ישיר','עותר שהוא עובד ציבור בלבד','עותר מטעם הממשלה'],'עותר ציבורי מכוון לאינטרס כללי. נפגע ישיר הוא הקטגוריה הישנה; מעמד עובד ציבור או מטעם הממשלה אינו קריטריון.'),
Q('בהלכת רסלר הובחן בין:','שפיטות נורמטיבית למוסדית',['חוק לחוק יסוד','זכות לחובה','בטלות לבטלות מושהית'],'רסלר הציבה את ההבחנה בין שפיטות נורמטיבית למוסדית. שאר הזוגות מתייחסים לנושאים אחרים (עליונות, סעדים).'),
Q('שפיטות נורמטיבית שואלת:','האם קיימת אמת מידה משפטית להכריע',['האם ראוי שביהמ"ש יכריע','האם יש עותר ציבורי','האם העתירה בשלה'],'השאלה היא על קיום נורמה משפטית. מוסדית עוסקת בראוי שביהמ"ש יכריע, ובשלות ועמידה הן עילות אחרות.'),
Q('שפיטות מוסדית שואלת:','האם ראוי שבית המשפט יכריע בעניין',['האם יש נפגע ישיר','האם קיימת נורמה','האם עבר שיהוי'],'שפיטות מוסדית מתמקדת בשאלה אם ההכרעה מתאימה לבית המשפט או לזירה הפוליטית. נורמה, עמידה ושיהוי הם עניינים נפרדים.'),
Q('מהי "בשלות"?','שהעתירה אינה מוקדמת מדי להכרעה',['שהעותר נפגע ישיר','שהחוק ישן','שהעתירה הוגשה מוקדם ככל האפשר'],'בשלות היא תנאי שהנושא התגבש להכרעה. נפגע ישיר שייך לעמידה, וחוק ישן אינו מבחן, והקדמה היא ההפך מבשלות.'),
Q('בסבח נ׳ הכנסת נדחו העתירות בשל:','חוסר בשלות',['חוסר זכות עמידה','חוסר שפיטות מוסדית','שיהוי'],'העתירות נדחו כי החוק טרם יושם והפגיעה לא התבררה. עמידה, שפיטות ושיהוי לא היו הנימוק.'),
Q('מהו "שיהוי"?','עיכוב בלתי סביר בהגשת העתירה',['עתירה מוקדמת','חוסר נפגע ישיר','חוסר שפיטות'],'שיהוי הוא איחור בעתירה, העלול לפגוע בצדדים. עתירה מוקדמת היא חוסר בשלות.'),
Q('מהי בטלות מושהית?','פסילה עם דחיית הבטלות לפרק זמן',['בטלות מיידית','פרשנות מקיימת','דחיית העתירה'],'בטלות מושהית נותנת לכנסת זמן לתקן. מיידית היא ההפך, ופרשנות או דחייה אינן סעד פסילה.'),
Q('מה פירוש "פרשנות מקיימת"?','פרשנות החוק כך שיעמוד בחוק היסוד',['פסילת החוק','קביעת רוב מיוחד','דחיית עתירה על הסף'],'פרשנות מקיימת מאפשרת להימנע מפסילה על ידי בחירת פירוש חוקתי. פסילה היא כלי חמור יותר.'),
Q('איזה סעד נחשב מתון ביותר?','פרשנות מקיימת',['בטלות מלאה','בטלות מיידית','ביטול חוק יסוד'],'פרשנות מקיימת שומרת על החוק. בטלות מלאה או מיידית חריפות יותר, וביטול חוק יסוד חריג.'),
Q('חוק טל נבחן בבג"ץ בעיקר בשל פגיעה ב:','שוויון',['קניין','חופש הביטוי','חופש העיסוק'],'חוק טל עסק בדחיית שירות תלמידי ישיבות ובשוויון בנטל. קניין, ביטוי ועיסוק אינם הנושא.'),
Q('מהי גישת "הכול שפיט"?','כמעט לכל נושא יש היבט משפטי ולכן הוא שפיט נורמטיבית',['שאין נושא שפיט','שרק זכויות שפיטות','שהכנסת אינה שפיטה'],'הגישה מרחיבה את השפיטות. שלילת שפיטות או הגבלתה לזכויות בלבד אינה הגישה.'),
Q('מה הביקורת על הרחבת השפיטות?','שהיא מושכת סוגיות פוליטיות לבית המשפט',['שהיא מצמצמת זכויות','שהיא מונעת עתירות','שהיא מרחיבה את הכנסת'],'הביקורת היא אובדן הפרדת הרשויות. היא אינה מצמצמת זכויות או מונעת עתירות.'),
Q('איזה מאלה אינו תנאי סף?','סיכוי לזכות בעתירה',['בשלות','שיהוי','עמידה'],'סיכוי לזכות הוא עניין לגופו של עניין ולא תנאי סף. בשלות, שיהוי ועמידה הם תנאי סף.'),
Q('מתי מכירים בדרך כלל בעותר ציבורי?','כשהנושא חוקתי עקרוני או נוגע לשלטון החוק',['תמיד','לעולם לא','רק בשבת'],'ההכרה נעשית לפי חשיבות הנושא. תמיד או לעולם לא הן הגזמות.'),
Q('בהפרטת בתי הסוהר נקבע סעד של:','בטלות מושהית',['דחיית עתירה','פרשנות מקיימת בלבד','פסילת חוק יסוד'],'בית המשפט פסל את התיקון והשהה את הבטלות. לא נדחתה העתירה ולא נפסל חוק יסוד.'),
Q('מה משמעות "מיצוי הליכים"?','פנייה קודם לגורם המתאים לפני בג"ץ',['מחיקת העתירה','בקשה לדיון נוסף','חובת עותר ציבורי'],'מיצוי הליכים דורש פנייה לרשות או לערכאה מתאימה, ולא פנייה ישירה לבג"ץ.'),
Q('מה ההבדל בין עמידה לשפיטות?','עמידה עוסקת בעותר, שפיטות בנושא',['אין הבדל','עמידה בנושא, שפיטות בעותר','שניהם בעניין סעד'],'עמידה בודקת את מעמד העותר, ושפיטות את ראוי הנושא להכרעה.'),
Q('אם החוק נפגע במקום מסוים בלבד, איזה סעד סביר?','בטלות חלקית',['בטלות מלאה בלבד','אין סעד','ביטול הכנסת'],'כשהפגם מצומצם, מבטלים רק את ההוראה. בטלות מלאה בלבד אינה הכרחית.'),
]
